/* Shared engine for every CCE 114 self-check quiz.
 *
 * Each quiz page is a small shell: the same markup, this script, and a
 * <script type="application/json" id="quizData"> block holding that quiz's questions.
 * Pages are generated by tools/build_quiz.py from the data files in tools/quizzes/.
 * Fix a behaviour here and every quiz gets it.
 */
(function () {
  "use strict";

  var data = JSON.parse(document.getElementById("quizData").textContent);
  var questions = data.questions;
  var messages = data.messages;          // [perfect, good, keep-going]
  var LETTERS = ["A", "B", "C", "D", "E", "F"];

  var el = {};
  ["sectionBadge", "promptText", "setupText", "optionsBox", "feedbackBox", "nextBtn",
   "progressText", "scoreText", "quizContent", "finalScreen", "finalScoreDisplay",
   "finalFeedbackText", "scoreBar", "restartBtn", "review"].forEach(function (id) {
    el[id] = document.getElementById(id);
  });

  var index = 0;
  var score = 0;
  var answered = false;
  var missed = [];

  function loadQuestion() {
    answered = false;
    var q = questions[index];

    el.sectionBadge.textContent = q.section;
    el.promptText.textContent = q.prompt;
    el.setupText.textContent = q.setup || "";
    el.setupText.style.display = q.setup ? "block" : "none";

    el.optionsBox.innerHTML = "";
    q.options.forEach(function (text, i) {
      var btn = document.createElement("button");
      btn.className = "opt-btn";
      var letter = document.createElement("span");
      letter.className = "opt-letter";
      letter.textContent = LETTERS[i];
      var label = document.createElement("span");
      label.textContent = text;
      btn.appendChild(letter);
      btn.appendChild(label);
      btn.addEventListener("click", function () { checkAnswer(i); });
      el.optionsBox.appendChild(btn);
    });

    el.feedbackBox.className = "feedback";
    el.feedbackBox.innerHTML = "";
    el.nextBtn.style.display = "none";

    el.progressText.textContent = "Question " + (index + 1) + " of " + questions.length;
  }

  function checkAnswer(selected) {
    if (answered) return;
    answered = true;

    var q = questions[index];
    var right = selected === q.correct;
    if (right) score++;
    else missed.push({ prompt: q.prompt, answer: q.options[q.correct] });

    el.scoreText.textContent = "Score: " + score + " / " + (index + 1);

    el.optionsBox.querySelectorAll("button.opt-btn").forEach(function (btn, i) {
      btn.disabled = true;
      if (i === q.correct) btn.classList.add("correct");
      if (i === selected && !right) btn.classList.add("incorrect");
    });

    el.feedbackBox.classList.add("visible");
    el.feedbackBox.classList.add(right ? "correct-box" : "incorrect-box");
    var head = document.createElement("strong");
    head.textContent = (right ? "✓ Correct" : "✗ Not quite") +
                       " — " + LETTERS[q.correct] + ". " + q.options[q.correct];
    el.feedbackBox.appendChild(head);
    el.feedbackBox.appendChild(document.createTextNode(q.explanation));

    el.nextBtn.textContent = (index === questions.length - 1) ? "See how you did" : "Next →";
    el.nextBtn.style.display = "inline-block";
    el.nextBtn.focus();
  }

  function nextQuestion() {
    index++;
    if (index < questions.length) loadQuestion();
    else showResults();
  }

  function showResults() {
    el.quizContent.style.display = "none";
    el.scoreBar.style.display = "none";
    el.finalScreen.style.display = "block";
    el.finalScoreDisplay.textContent = score + " / " + questions.length;

    // Two thirds right is the "solid" line; everything below that gets the nudge.
    var good = Math.ceil(questions.length * 2 / 3);
    el.finalFeedbackText.textContent =
      score === questions.length ? messages[0] : (score >= good ? messages[1] : messages[2]);

    el.review.innerHTML = "";
    if (missed.length) {
      var h = document.createElement("h3");
      h.textContent = missed.length === 1 ? "The one to go back to" : "The ones to go back to";
      var ul = document.createElement("ul");
      missed.forEach(function (m) {
        var li = document.createElement("li");
        li.textContent = m.prompt;
        var ans = document.createElement("span");
        ans.textContent = m.answer;
        li.appendChild(ans);
        ul.appendChild(li);
      });
      el.review.appendChild(h);
      el.review.appendChild(ul);
    }
  }

  function restartQuiz() {
    index = 0;
    score = 0;
    el.scoreBar.style.display = "flex";
    el.quizContent.style.display = "block";
    el.finalScreen.style.display = "none";
    el.scoreText.textContent = "Score: 0 / 0";
    missed = [];
    el.review.innerHTML = "";
    loadQuestion();
  }

  document.addEventListener("keydown", function (e) {
    if (el.finalScreen.style.display === "block") return;
    if (e.key === "Enter" && answered) { nextQuestion(); return; }
    var k = e.key.toUpperCase();
    var i = LETTERS.indexOf(k);
    if (i === -1 && k >= "1" && k <= "6") i = Number(k) - 1;
    if (i > -1 && i < questions[index].options.length && !answered) {
      e.preventDefault();
      checkAnswer(i);
    }
  });

  el.nextBtn.addEventListener("click", nextQuestion);
  el.restartBtn.addEventListener("click", restartQuiz);

  // Exposed so the page can be driven from the console when checking a quiz.
  window.quiz = {
    get questions() { return questions; },
    get score() { return score; },
    checkAnswer: checkAnswer,
    nextQuestion: nextQuestion,
    restart: restartQuiz
  };

  loadQuestion();
})();
